(function frame(x, z) {
  const app = window.__CITY_APP;
  // (a diagnostic framing: the street trees go to an unused layer, out of the view and the shadow maps alike, so
  // nothing stands between the camera and the pole's shadow)
  app.scene.traverse((o) => { if (o.isMesh && /^Trees|Tree/.test(o.name)) o.layers.set(7); });
  let best = null, bd = Infinity;
  app.scene.getObjectByName('CityStreetDetails').traverse((o) => {
    if (!o.isInstancedMesh || o.geometry.index?.count !== 120 || !(o.name === '' || o.name === 'StreetPoles')) return;
    const e = o.instanceMatrix.array;
    for (let i = 0; i < o.count; i++) {
      const k = i * 16, h = Math.hypot(e[k + 4], e[k + 5], e[k + 6]);
      if (h < 8.9) continue;
      const d = Math.hypot(e[k + 12] - x, e[k + 14] - z);
      if (d < bd) { bd = d; best = { x: e[k + 12], y: e[k + 13] - h / 2, z: e[k + 14], h }; }
    }
  });
  const view = () => {
    const s = app.lightingSystem.sunLight.position.clone().normalize();
    const hz = Math.hypot(s.x, s.z) || 1;
    const sx = -s.x / hz, sz = -s.z / hz, len = Math.min(14, best.h * hz / Math.max(0.05, s.y));
    const px = -sz, pz = sx;
    const P = [best.x + sx * len * 0.55, best.y + 0.1, best.z + sz * len * 0.55];
    return { s, sx, sz, px, pz, P };
  };
  const v0 = view();
  app.teleportTo(best.x + v0.px * 3, best.z + v0.pz * 3, Math.atan2(v0.sx, v0.sz));
  app.cameraSystem.cinema = () => {
    const { sx, sz, px, pz, P } = view();
    return { pos: [P[0] + px * 9 - sx * 5, best.y + 11, P[2] + pz * 9 - sz * 5], look: P, fov: 50 };
  };
  const s = v0.s;
  console.log('[ride-check] pole ' + JSON.stringify({ x: +best.x.toFixed(1), z: +best.z.toFixed(1), h: best.h, sun: [s.x, s.y, s.z].map((v) => +v.toFixed(3)), q: location.search }));
  return best;
})(-996.1, -720)

